package glitch

import data.glitch_lib

# Set of weak algorithms and protocols for CWE-327
weak_algorithms := {
    "des", "3des", "tdes", "rc2", "rc4", "arc4", "blowfish", "aes-ecb", "aes_ecb",
    "md2", "md4", "md5", "sha-1", "sha1", "rot-13", "rot13", "base64", "xor",
    "sslv2", "sslv3", "tls1.0", "tls1.0", "tls1.1", "sshv1", "md5_crypt"
}

# Check if a string value contains any weak algorithm (case-insensitive)
contains_weak_algorithm(str) {
    some weak_alg
    weak_algorithms[weak_alg]
    regex.match(sprintf("(?i).*%s.*", [weak_alg]), str)
}

# Check a single value node for weak algorithms
check_value_for_weak_algo(value) {
    value.ir_type == "String"
    contains_weak_algorithm(value.value)
} else {
    # For function calls, check the name and arguments
    value.ir_type == "FunctionCall"
    contains_weak_algorithm(value.name)
} else {
    # For function calls, also check arguments
    value.ir_type == "FunctionCall"
    some arg
    arg := value.args[_]
    check_value_for_weak_algo(arg)
}

# Check attributes for weak algorithms
check_attribute_for_weak_algo(attr) {
    # Direct string value check
    attr.value.ir_type == "String"
    contains_weak_algorithm(attr.value.value)
} else {
    # Check function calls in the value
    check_value_for_weak_algo(attr.value)
} else {
    # Check complex values (Hash, Array) recursively
    attr.value.ir_type in {"Hash", "Array"}
    traverse_complex_value(attr.value)
}

# Traverse complex values (Hash or Array) to find weak algorithms
traverse_complex_value(complex) {
    walk(complex, [path, node])
    node.ir_type == "String"
    contains_weak_algorithm(node.value)
}

# Main detection rule for AtomicUnit attributes (Ansible, Chef, Puppet resources)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    check_attribute_for_weak_algo(attr)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm (CWE-327)"
    }
}

# Detection rule for Variables (Chef attributes, Ansible variables)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    check_value_for_weak_algo(var.value)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm (CWE-327)"
    }
}

# Detection rule for nested Hash values in variables/attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    var.value.ir_type in {"Hash", "Array"}
    traverse_complex_value(var.value)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm (CWE-327)"
    }
}

